function mover(saldo, cambio) {
  if (cambio !== 0) {
    const saldo = saldo + cambio;
  }
  return saldo;
}

function aplicarMovimiento(saldoInicial, movimientoTexto) {
  let saldo = Number(saldoInicial);

  if (movimientoTexto !== '') {
    const saldo = saldo + Number(movimientoTexto);
  }

  return saldo;
}
